PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS c_canvases(id TEXT PRIMARY KEY,title TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,last_op TEXT,creator TEXT NOT NULL,created_at INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS c_pixels(canvas_id TEXT NOT NULL REFERENCES c_canvases(id),x INTEGER NOT NULL,y INTEGER NOT NULL,color INTEGER NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(canvas_id,x,y));
CREATE TABLE IF NOT EXISTS c_pixel_changes(canvas_id TEXT NOT NULL,revision INTEGER NOT NULL,x INTEGER NOT NULL,y INTEGER NOT NULL,color INTEGER NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(canvas_id,revision,x,y));
CREATE INDEX IF NOT EXISTS c_changes_since ON c_pixel_changes(canvas_id,revision);
CREATE TABLE IF NOT EXISTS c_debates(id TEXT PRIMARY KEY,title TEXT NOT NULL,context TEXT NOT NULL,creator TEXT NOT NULL,created_at INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS c_arguments(id TEXT PRIMARY KEY,debate_id TEXT NOT NULL REFERENCES c_debates(id),parent_id TEXT REFERENCES c_arguments(id),side INTEGER NOT NULL CHECK(side IN(0,1)),claim TEXT NOT NULL,reasoning TEXT NOT NULL,evidence_url TEXT NOT NULL,creator TEXT NOT NULL,created_at INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS c_arguments_debate ON c_arguments(debate_id,created_at);
CREATE TABLE IF NOT EXISTS c_reviews(argument_id TEXT NOT NULL REFERENCES c_arguments(id),visitor TEXT NOT NULL,clarity INTEGER NOT NULL CHECK(clarity BETWEEN 1 AND 3),evidence INTEGER NOT NULL CHECK(evidence BETWEEN 1 AND 3),PRIMARY KEY(argument_id,visitor));
CREATE TABLE IF NOT EXISTS c_exchanges(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('offer','request')),title TEXT NOT NULL,skill TEXT NOT NULL,description TEXT NOT NULL,minutes INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','matched','completed','closed')),creator TEXT NOT NULL,matched_thread TEXT,created_at INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS c_threads(id TEXT PRIMARY KEY,exchange_id TEXT NOT NULL REFERENCES c_exchanges(id),requester TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'proposed' CHECK(status IN('proposed','accepted','declined','withdrawn','completed')),owner_done INTEGER NOT NULL DEFAULT 0,requester_done INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,UNIQUE(exchange_id,requester));
CREATE TABLE IF NOT EXISTS c_messages(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES c_threads(id),sender TEXT NOT NULL,body TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS c_messages_thread ON c_messages(thread_id,created_at);
CREATE TABLE IF NOT EXISTS c_museums(id TEXT PRIMARY KEY,title TEXT NOT NULL,theme TEXT NOT NULL,description TEXT NOT NULL,creator TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,last_op TEXT,created_at INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS c_objects(id TEXT PRIMARY KEY,museum_id TEXT NOT NULL REFERENCES c_museums(id),title TEXT NOT NULL,story TEXT NOT NULL,era TEXT NOT NULL,creator TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','approved','rejected')),position INTEGER NOT NULL,created_at INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS c_objects_museum ON c_objects(museum_id,status,position);
CREATE TABLE IF NOT EXISTS c_rooms(id TEXT PRIMARY KEY,title TEXT NOT NULL,scenario INTEGER NOT NULL,solution_hash TEXT NOT NULL,creator TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','solved')),created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS c_room_clues(room_id TEXT NOT NULL REFERENCES c_rooms(id),role INTEGER NOT NULL CHECK(role BETWEEN 0 AND 3),clue TEXT NOT NULL,PRIMARY KEY(room_id,role));
CREATE TABLE IF NOT EXISTS c_players(room_id TEXT NOT NULL REFERENCES c_rooms(id),role INTEGER NOT NULL,visitor TEXT NOT NULL,joined_at INTEGER NOT NULL,PRIMARY KEY(room_id,role),UNIQUE(room_id,visitor));
CREATE TABLE IF NOT EXISTS c_room_messages(id TEXT PRIMARY KEY,room_id TEXT NOT NULL REFERENCES c_rooms(id),role INTEGER NOT NULL,body TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS c_room_messages_time ON c_room_messages(room_id,created_at);
CREATE TABLE IF NOT EXISTS c_reports(kind TEXT NOT NULL,target_id TEXT NOT NULL,network TEXT NOT NULL,reason TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(kind,target_id,network));
CREATE TABLE IF NOT EXISTS c_rates(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS c_rates_expiry ON c_rates(expires_at);
